8	export interface Page {
9	  /** Path to the source markdown file, relative to the content directory. */
10	  sourcePath: string;
11	  /** URL-friendly slug derived from the source path, without extension. */
12	  slug: string;
13	  /** Output file name, e.g. "about.html". */
14	  outputFile: string;
15	  title: string;
16	  date: string | undefined;
17	  tags: string[];
18	  html: string;
19	}
