1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseMarkdown } from './parser';
4	import { renderIndex, renderPage } from './templates';
5	import { BuildOptions, BuildResult, Page } from './types';
6	
7	const MARKDOWN_EXTENSIONS = new Set(['.md', '.markdown']);
8	
9	/**
10	 * Recursively finds markdown files under `dir`, returning paths relative to
11	 * `dir` (using forward slashes).
12	 */
13	export function findMarkdownFiles(dir: string): string[] {
14	  const results: string[] = [];
15	
16	  function walk(current: string) {
17	    const entries = fs.readdirSync(current, { withFileTypes: true });
18	    for (const entry of entries) {
19	      const fullPath = path.join(current, entry.name);
20	      if (entry.isDirectory()) {
21	        walk(fullPath);
22	      } else if (MARKDOWN_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) {
23	        results.push(path.relative(dir, fullPath).split(path.sep).join('/'));
24	      }
25	    }
26	  }
27	
28	  if (fs.existsSync(dir)) {
29	    walk(dir);
30	  }
31	
32	  return results;
33	}
34	
35	export function loadPages(contentDir: string): Page[] {
36	  const files = findMarkdownFiles(contentDir);
37	  return files.map((relativePath) => {
38	    const raw = fs.readFileSync(path.join(contentDir, relativePath), 'utf-8');
39	    return parseMarkdown(raw, relativePath);
40	  });
41	}
42	
43	function writeFile(filePath: string, contents: string) {
44	  fs.mkdirSync(path.dirname(filePath), { recursive: true });
45	  fs.writeFileSync(filePath, contents, 'utf-8');
46	}
47	
48	const DEFAULT_STYLESHEET = `body { font-family: sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
49	header { margin-bottom: 2rem; }
50	.page-list { list-style: none; padding: 0; }
51	.page-list li { margin-bottom: 0.5rem; }
52	.tags { list-style: none; padding: 0; display: flex; gap: 0.5rem; }
53	.tags li { background: #eee; border-radius: 0.25rem; padding: 0.1rem 0.5rem; font-size: 0.85rem; }
54	`;
55	
56	export function buildSite(options: BuildOptions): BuildResult {
57	  const { contentDir, outputDir } = options;
58	
59	  if (!fs.existsSync(contentDir)) {
60	    throw new Error(`Content directory not found: ${contentDir}`);
61	  }
62	
63	  const pages = loadPages(contentDir);
64	
65	  fs.mkdirSync(outputDir, { recursive: true });
66	
67	  for (const page of pages) {
68	    writeFile(path.join(outputDir, page.outputFile), renderPage(page));
69	  }
70	
71	  writeFile(path.join(outputDir, 'index.html'), renderIndex(pages));
72	  writeFile(path.join(outputDir, 'style.css'), DEFAULT_STYLESHEET);
73	
74	  return { pages, outputDir };
75	}
