1	import { Page } from './types';
2	
3	export function escapeHtml(input: string): string {
4	  return input
5	    .replace(/&/g, '&amp;')
6	    .replace(/</g, '&lt;')
7	    .replace(/>/g, '&gt;')
8	    .replace(/"/g, '&quot;')
9	    .replace(/'/g, '&#39;');
10	}
11	
12	export function renderPage(page: Page): string {
13	  const tagsHtml = page.tags.length
14	    ? `<ul class="tags">${page.tags.map((t) => `<li>${escapeHtml(t)}</li>`).join('')}</ul>`
15	    : '';
16	  const dateHtml = page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
17	
18	  return `<!DOCTYPE html>
19	<html lang="en">
20	<head>
21	<meta charset="UTF-8">
22	<meta name="viewport" content="width=device-width, initial-scale=1.0">
23	<title>${escapeHtml(page.title)}</title>
24	<link rel="stylesheet" href="style.css">
25	</head>
26	<body>
27	<header>
28	<a href="index.html">&larr; Home</a>
29	</header>
30	<article>
31	<h1>${escapeHtml(page.title)}</h1>
32	${dateHtml}
33	${tagsHtml}
34	${page.html}
35	</article>
36	</body>
37	</html>
38	`;
39	}
40	
41	export function renderIndex(pages: Page[]): string {
42	  const sorted = [...pages].sort((a, b) => (b.date || '').localeCompare(a.date || ''));
43	  const items = sorted
44	    .map((page) => {
45	      const dateHtml = page.date ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
46	      return `<li><a href="${escapeHtml(page.outputFile)}">${escapeHtml(page.title)}</a>${dateHtml}</li>`;
47	    })
48	    .join('\n');
49	
50	  return `<!DOCTYPE html>
51	<html lang="en">
52	<head>
53	<meta charset="UTF-8">
54	<meta name="viewport" content="width=device-width, initial-scale=1.0">
55	<title>Home</title>
56	<link rel="stylesheet" href="style.css">
57	</head>
58	<body>
59	<header>
60	<h1>Home</h1>
61	</header>
62	<ul class="page-list">
63	${items}
64	</ul>
65	</body>
66	</html>
67	`;
68	}
